MultiLanguageItemData['ru'][229200] = {name = "Тройка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображен порыв ветра, разрывающий сердце на части; на заднем фоне мрачные облака, из которых льет дождь.\""}
MultiLanguageItemData['ru'][229201] = {name = "Четверка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображена статуя молящегося рыцаря, которая стоит над могилой. Скорее всего, это могила рыцаря.\""}
MultiLanguageItemData['ru'][229202] = {name = "Пятерка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображен мужчина, который презрительно взирает на две отчаянно удирающие фигуры. Беглецы бросили свои мешки с воздухом на землю. Два других мешка – на левом плече мужчины, а третий он держит в правой руке.\""}
MultiLanguageItemData['ru'][229203] = {name = "Шестерка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображен паромщик, перевозящий пассажиров на другой берег. Течение спокойное, груз легкий и, судя по всему, поездка пройдет удачно.\""}
MultiLanguageItemData['ru'][229204] = {name = "Семерка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображен человек, уносящий пять ветров. Два других ветра лежат на земле, а вблизи виднеется лагерь.\""}
MultiLanguageItemData['ru'][229205] = {name = "Восьмерка из колоды Воздуха", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображен связанный пленник с повязкой на глазах, а вокруг – восемь буйных ветров. Но, похоже, эти путы временные, и скоро пленник освободится.\""}
MultiLanguageItemData['ru'][229206] = {name = "Туз из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображена рука, которая тянется из пылающего шара. Она сжимает жезл, окруженный дымом.\""}
MultiLanguageItemData['ru'][229207] = {name = "Двойка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображена высокая фигура, стоящая на крепостной стене над берегом моря. В правой руке у нее – сфера, а в левой – посох, объятый пламенем. Еще один пылающий посох закреплен в кольце справа от фигуры.\""}
MultiLanguageItemData['ru'][229208] = {name = "Тройка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображена статная фигура, стоящая над обрывом. Она повернута спиной к зрителю и, похоже, смотрит, как по морю внизу проплывают корабли. В землю воткнуто три посоха, на каждом из которых висит фонарь. Человек расслабленно опирается на один из посохов.\""}
MultiLanguageItemData['ru'][229209] = {name = "Четверка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображены четыре колонны, на которых висит гирлянда чистейшего пламени. Два человека держат ароматные цветы, неподалеку от них – ров, а надо рвом – мост, ведущий к старому особняку.\""}
MultiLanguageItemData['ru'][229210] = {name = "Пятерка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображена компания из пяти молодых людей, которые размахивают посохами, будто сражаются. Похоже, они играют в войну, глаза у них горят огнем.\""}
MultiLanguageItemData['ru'][229211] = {name = "Шестерка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"Тут изображен всадник на коне. На голове у него – лавровый венец, а в руках – пылающий меч. За ним следует пять пехотинцев с такими же пылающими мечами.\""}
MultiLanguageItemData['ru'][229212] = {name = "Семерка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображен полный решимости человек. Он стоит на скалистом холме, высоко подняв факел. Под ним другие люди поднимают еще шесть факелов.\""}
MultiLanguageItemData['ru'][229213] = {name = "Восьмерка из колоды Огня", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображены восемь пылающих стрел, летящих по небу. То, что они символизируют, уже близко. Возможно, даже на пороге.\""}
MultiLanguageItemData['ru'][229214] = {name = "Туз из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображена рука, которая тянется из земель, покрытых свежим снегом. Она сжимает ручку кубка, до краев наполненного водой. От кубка исходит пар.\""}
MultiLanguageItemData['ru'][229215] = {name = "Двойка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображены два молодых человека посреди зимы. Они поднимают фляги, сделанные из чистого льда.\""}
MultiLanguageItemData['ru'][229216] = {name = "Тройка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображены праздные гуляки, танцующие в саду под снегопадом. Они поднимают кубки, будто приносят друг другу клятву.\""}
MultiLanguageItemData['ru'][229217] = {name = "Четверка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"Здесь изображен человек в мехах, сидящий под сосной и созерцающий три чаши, которые стоят перед ним в снегу. Рука из облака протягивает ему четвертую чашу. Судя по лицу человека, ему что-то сильно не нравится.\""}
MultiLanguageItemData['ru'][229218] = {name = "Пятерка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображена мрачная фигура в плаще, изучающая три перевернутых кубка, из которых вылилась вся вода. Два других кубка стоят позади человека на ледяных пьедесталах. На заднем плане виднеется мост, ведущий к маленькой крепости.\""}
MultiLanguageItemData['ru'][229219] = {name = "Шестерка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте – дети в старом саду. Они поливают цветы из кубков, полных тающего снега.\""}
MultiLanguageItemData['ru'][229220] = {name = "Семерка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте странные образы изливаются из семи чаш, отлитых из чистейшего льда. Все эти образы порождены духом фантазии.\""}
MultiLanguageItemData['ru'][229221] = {name = "Восьмерка из колоды Льда", additional_info = "Колода Новолуния для предсказаний\n[q]\"На этой карте изображен человек, уходящий прочь с опущенной головой. Позади него остаются кубки с его богатством, прошлыми начинаниями, обязательствами и тревогами. Все их скоро поглотит наползающая ледяная корка.\""}
MultiLanguageItemData['ru'][229222] = {name = "Туз из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображена рука в облаке пыли, выступающая сквозь скалистую землю. Рука держит каменный диск.\""}
MultiLanguageItemData['ru'][229223] = {name = "Двойка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображен ребенок, танцующий с каменным диском в каждой руке. Диски соединены бесконечным шнуром, напоминающим перевернутую восьмерку.\""}
MultiLanguageItemData['ru'][229224] = {name = "Тройка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображен скульптор за работой в монастыре. Ученик получил свою награду и теперь полностью погрузился в работу.\""}
MultiLanguageItemData['ru'][229225] = {name = "Четверка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображена фигура в короне с каменным диском над головой, еще одним диском в руках и двумя под ногами. Она крепко держится за то, что имеет.\""}
MultiLanguageItemData['ru'][229226] = {name = "Пятерка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображены двое нищих, идущих сквозь пыльную бурю мимо окна, где виднеется пять сверкающих каменных дисков.\""}
MultiLanguageItemData['ru'][229227] = {name = "Шестерка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображен человек в одежде торговца. Он взвешивает золото на весах и раздает его страждущим. Значит, он не только добился в жизни успеха, но и не растерял доброты.\""}
MultiLanguageItemData['ru'][229228] = {name = "Семерка из колоды Земли", additional_info = "Колода Новолуния для предсказаний\n[q]\"На карте изображен молодой человек, опирающийся на посох и всматривающийся в семь каменных дисков на фоне зелени справа. Возможно, это и есть сокровища, которые так дороги его сердцу.\""}
