MultiLanguageItemData['ru'][229388] = {name = "[q2]Геральдика призового бойца", additional_info = "The War Within, 2-й сезон\nДополнительный реагент\n\n[q2]Дает свойство: Сертифицирует предмет для боев в PvP, позволяя ему масштабироваться до 658-го уровня.\n\n Для изготовления требуется несколько таких реагентов.\n[q]\"Можно добыть, выполняя различные PvP-задачи, или приобрести за очки чести у PvP-интендантов в Дорногале. Также можно купить или продать на аукционе.\""}
MultiLanguageItemData['ru'][229389] = {name = "[q3]Геральдика призового претендента", additional_info = "The War Within, 2-й сезон\nСтановится персональным при получении\nДополнительный реагент\n[q2]+50 Уровень рецепта\n[q2]Дает свойство: Сертифицирует предмет для боев в PvP, позволяя ему масштабироваться до 671-го уровня.\n\n Для изготовления требуется несколько таких реагентов.\n[q]\"Приобретается за очки чести у PvP-интендантов в Дорногале.\""}
MultiLanguageItemData['ru'][229390] = {name = "[q4]Геральдика призового гладиатора", additional_info = "The War Within, 2-й сезон\nСтановится персональным при получении\nДополнительный реагент\n[q2]+150 Уровень рецепта\n[q2]Дает свойство: Сертифицирует предмет для боев в PvP, позволяя ему масштабироваться до 684-го уровня.\n\n Для изготовления требуется несколько таких реагентов.\n[q]\"Приобретается за очки завоевания у PvP-интендантов в Дорногале.\""}
MultiLanguageItemData['ru'][229392] = {name = "Смятая накладная", additional_info = "Требуется для задания\nТребуемый уровень: 80 - 80 ( 80)\n[q]\"Письмо к банде Нижнегонса, где расписана плата в виде оружия.\""}
MultiLanguageItemData['ru'][229401] = {name = "[q2]Брошюра Консорциума ремесленников", additional_info = "Становится персональным при получении\nУникальный\nЭтот предмет позволяет получить задание.\n[q]\"Особое уведомление для участников всех уровней!\""}
MultiLanguageItemData['ru'][229405] = {name = "Энтропический сердечник", additional_info = "Требуется для задания\n[q]\"Концентрированная энергия, вытянутая из почвы К'ареша.\""}
MultiLanguageItemData['ru'][229407] = {name = "Цитрусовая кислота", additional_info = "Требуется для задания\n[q]\"Улучшает вкус грога. Или нет. По правде говоря, это большой вопрос.\""}
MultiLanguageItemData['ru'][229408] = {name = "Обгорелое перо", additional_info = "Тайны Азерота\nТребуется для задания Уникальный\n[q]\"Это перо явно побывало в битвах. Оно обгорело, местами подрано, а с кончика капает странная зеленая жидкость.\""}
MultiLanguageItemData['ru'][229409] = {name = "Выдернутое перо", additional_info = "Тайны Азерота\nТребуется для задания Уникальный\n[q]\"Похоже, это перо выдернули специально. У него не хватает ровно 48 бородок слева, а справа осталось 93 бородки.\""}
MultiLanguageItemData['ru'][229410] = {name = "Замороженное перо", additional_info = "Тайны Азерота\nТребуется для задания Уникальный\n[q]\"Замерзшее перо пахнет странной смесью ароматов вулканического пепла, соленой воды и машинного масла.\""}
MultiLanguageItemData['ru'][229411] = {name = "Обычное перо", additional_info = "Тайны Азерота\nТребуется для задания Уникальный\n[q]\"Перо выглядит абсолютно обычно, как и полагается в начале путешествия.\""}
